,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' nTotalProductores       number := 0;',
' nTotalProductoresRegistrados       number := 0;',
'begin',
' HTP.P(''<!DOCTYPE html>'');',
'  HTP.P(''<html lang="en" dir="ltr">'');',
'    HTP.P(''<head>'');',
'      HTP.P(''<meta charset="UTF-8">'');',
'      HTP.P(''<title> Responsiive Admin Dashboard | CodingLab </title>'');',
'      HTP.P(''<link rel="stylesheet" href="style.css">'');',
'      HTP.P(''<link href="https://unpkg.com/boxicons@2.0.7/css/boxicons.min.css" rel="stylesheet">'');',
'      HTP.P(''<meta name="viewport" content="width=device-width, initial-scale=1.0">'');',
'    HTP.P(''</head>'');',
'  HTP.P(''<style>',
'  .t-Region-body {',
'    background-color: #edf3ff;',
'  }',
'  .t-Region {',
'      border-radius: 0px;',
'  }',
'  .col,.t-Body-contentInner  {padding: 0px} ',
'  .home-section .home-CONTENT{',
'    POSITION: relative;',
'    padding-top: 104px;',
'  }',
'  .home-content .overview-boxes{',
'    display: flex;',
'  ',
'    justify-CONTENT: SPACE-BETWEEN;',
'    flex-wrap: wrap;',
'    padding: 0 20px;',
'    margin-bottom: 26px;',
'  }',
'',
'  .overview-boxes .box{',
'    display: flex;',
'    flex-direction: column;',
'    align-items: center;',
'    width: calc(100% / 4 - 15px);',
'    background: #F7FAFF;',
'    padding: 15px 14px;',
'    border-radius: 6px;',
'    box-shadow: 0 5px 10px rgba(0,0,0,0.1);',
'  }',
'  .overview-boxes .box-topic{',
'    font-SIZE: 18px;',
'    font-weight: 800;',
'    color: #0033a0;',
'  }',
'  .home-content .box .PRICE{',
'    display: INLINE-BLOCK;',
'    font-SIZE: 26px;',
'    margin-top: 16px;',
'    font-weight: 500;',
'    color: #444;',
'  }',
'  .right-side {',
'    text-align: center;',
'  }',
'  .PRICE_xs{',
'    font-SIZE: 22px;',
'    margin-top: 10px;',
'    font-weight: 500;',
'    color: #444;',
'  }',
'  .home-content .box .INDICATOR{',
'    display: flex;',
'    align-items: center;',
'    margin-top: 10px;',
'  }',
'  .home-content .box .INDICATOR i{',
'    height: 20px;',
'    width: 20px;',
'    background: #8FDACB;',
'    line-height: 20px;',
'    text-align: center;',
'    border-radius: 50%;',
'    color: #fff;',
'    font-SIZE: 20px;',
'    margin-RIGHT: 5px;',
'  }',
'  .box .INDICATOR i.DOWN{',
'    background: #e87d88;',
'  }',
'  .home-content .box .INDICATOR .text{',
'    font-SIZE: 12px;',
'  }',
'  .home-content .box .cart{',
'    display: INLINE-BLOCK;',
'    font-SIZE: 32px;',
'    height: 50px;',
'    width: 50px;',
'    background: #cce5ff;',
'    line-height: 50px;',
'    text-align: center;',
'    color: #66b0ff;',
'    border-radius: 6px;',
'    margin: -3px 0 0 20px;',
'  }',
'  .home-content .box .cart.two{',
'    color: #2BD47D;',
'    background: #C0F2D8;',
'  }',
'  .home-content .box .cart.three{',
'    color: #ffc233;',
'    background: #ffe8b3;',
'  }',
'  .home-content .box .cart.four{',
'    color: #e05260;',
'    background: #f7d4d7;',
'  }',
'  .home-content .total-ORDER{',
'    font-SIZE: 20px;',
'    font-weight: 500;',
'  }',
'  .home-content .sales-boxes{',
'    display: flex;',
'    justify-CONTENT: SPACE-BETWEEN;',
'',
'    /* padding: 0 20px; */',
'  }',
'',
'  /* left box */',
'  .home-content .sales-boxes .recent-sales{',
'    width: 65%;',
'    background: #edf3ff;',
'    padding: 20px 30px;',
'    margin: 0 20px;',
'    border-radius: 6px;',
'    box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);',
'  }',
'  .home-content .sales-boxes .sales-details{',
'    display: flex;',
'    align-items: center;',
'    justify-CONTENT: SPACE-BETWEEN;',
'  }',
'  .sales-boxes .box .title{',
'    font-SIZE: 24px;',
'    font-weight: 500;',
'',
'    /* margin-bottom: 10px; */',
'  }',
'  .sales-boxes .sales-details li.topic{',
'    font-SIZE: 20px;',
'    font-weight: 500;',
'  }',
'  .sales-boxes .sales-details li{',
'  list-style: none;',
'    margin: 8px 0;',
'  }',
'  .sales-boxes .sales-details li A{',
'    font-SIZE: 18px;',
'    color: #333;',
'    font-SIZE: 400;',
'    text-decoration: NONE;',
'  }',
'  .sales-boxes .box .button{',
'    width: 100%;',
'    display: flex;',
'    justify-CONTENT: flex-END;',
'  }',
'  .sales-boxes .box .button A{',
'    color: #fff;',
'    background: #0A2558;',
'    padding: 4px 12px;',
'    font-SIZE: 15px;',
'    font-weight: 400;',
'    border-radius: 4px;',
'    text-decoration: NONE;',
'    transition: ALL 0.3s ease;',
'  }',
'  .sales-boxes .box .button A:hover{',
'    background:  #0d3073;',
'  }',
'',
'  /* Right box */',
'  .home-content .sales-boxes .top-sales{',
'    width: 35%;',
'    background: #f8f8f8;',
'    padding: 20px 30px;',
'    margin: 0 20px 0 0;',
'    border-radius: 6px;',
'    box-shadow: 0 5px 10px rgba(0, 0, 0, 0.1);',
'  }',
'  .sales-boxes .top-sales li{',
'    display: flex;',
'    align-items: center;',
'    justify-CONTENT: SPACE-BETWEEN;',
'    margin: 10px 0;',
'  }',
'  .sales-boxes .top-sales li A img{',
'    height: 40px;',
'    width: 40px;',
'    OBJECT-fit: cover;',
'    border-radius: 6px;',
'    margin-RIGHT: 10px;',
'    background: #333;',
'  }',
'  .sales-boxes .top-sales li A{',
'    display: flex;',
'    align-items: center;',
'    text-decoration: NONE;',
'  }',
'  .sales-boxes .top-sales li .product,',
'  .price{',
'    font-SIZE: 17px;',
'    font-weight: 400;',
'    color: #333;',
'  }',
'',
'  /* Responsive Media Query */',
'  @media (max-width: 1240px) {',
'    .sidebar{',
'      width: 60px;',
'    }',
'    .sidebar.ACTIVE{',
'      width: 220px;',
'    }',
'    .home-section{',
'      width: calc(100% - 60px);',
'      LEFT: 60px;',
'    }',
'    .sidebar.ACTIVE ~ .home-section{',
'',
'      /* width: calc(100% - 220px); */',
'      OVERFLOW: hidden;',
'      LEFT: 220px;',
'    }',
'    .home-section NAV{',
'      width: calc(100% - 60px);',
'      LEFT: 60px;',
'    }',
'    .sidebar.ACTIVE ~ .home-section NAV{',
'      width: calc(100% - 220px);',
'      LEFT: 220px;',
'    }',
'  }',
'  @media (max-width: 1150px) {',
'    .home-content .sales-boxes{',
'      flex-direction: COLUMN;',
'    }',
'    .home-content .sales-boxes .box{',
'      width: 100%;',
'      OVERFLOW-x: scroll;',
'      margin-bottom: 30px;',
'    }',
'    .home-content .sales-boxes .top-sales{',
'      margin: 0;',
'    }',
'  }',
'  @media (max-width: 1000px) {',
'    .overview-boxes .box{',
'      width: calc(100% / 2 - 15px);',
'      margin-bottom: 15px;',
'    }',
'  }',
'  @media (max-width: 700px) {',
'    nav .sidebar-button .dashboard,',
'    nav .PROFILE-details .admin_name,',
'    nav .PROFILE-details i{',
'      display: NONE;',
'    }',
'    .home-section nav .PROFILE-details{',
'      height: 50px;',
'      MIN-width: 40px;',
'    }',
'    .home-content .sales-boxes .sales-details{',
'      width: 560px;',
'    }',
'  }',
'  @media (max-width: 550px) {',
'    .overview-boxes .box{',
'      width: 100%;',
'      margin-bottom: 15px;',
'    }',
'    .sidebar.ACTIVE ~ .home-section nav .PROFILE-details{',
'      display: NONE;',
'    }',
'  }',
'',
'  </style>'');',
'  HTP.P(''<body>'');',
'',
'    COUNT_PRODUCERS(nTotalProductores);',
'    COUNT_PORTAL_PRODUCERS(nTotalProductoresRegistrados);',
'  htp.p(''<div class="home-content">',
'        <div class="overview-boxes">',
'          <div class="box">',
'          <div class="box-topic">Total de Productores</div>',
'            <div class="right-side">',
'              <div class="PRICE">''|| nTotalProductores ||''</div>',
'            </div>',
'          </div>',
'          <div class="box">',
'            <div class="box-topic">Productores Registrados</div>',
'            <div class="right-side">',
'                <div class="PRICE">''|| nTotalProductoresRegistrados ||''</div>',
'            </div>',
'          </div>',
'          <div class="box">',
'            <div class="box-topic">Solicitudes de Voucher</div>',
'            <div class="right-side">',
'              <div class="PRICE"></div>',
'            </div>',
'          </div>',
'          <div class="box">',
'            <div class="box-topic">Nuevos Reportes</div>',
'            <div class="right-side">',
'              <div class="PRICE_xs"></div>',
'              <div class="PRICE_xs"></div>',
'            </div>',
'          </div>',
'        </div>'');',
'',
'  HTP.P(''</body>'');',
'  HTP.P(''</html>'');',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
