,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'VerificarIntermediario'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  cCodProductor cart_productores.capd_cd_productor%type;',
'  nExiste NUMBER(1) := 0;',
'begin',
'  -- Buscar en Clientes',
'  begin',
'    select capd_cd_productor',
'      into cCodProductor',
'      from cart_productores',
'     where capd_cd_productor = :p2_codigo;',
'  exception',
'     when no_data_found then',
'         apex_error.add_error',
unistr('            (p_message          => ''No Existe Datos del Productor con este C\00F3digo'','),
'             p_display_location => apex_error.c_inline_in_notification);',
'  end;',
'  -- Verificar si el Productor Ha Sido Registrado Anteriormente',
'  begin',
'    select 1',
'      into nExiste',
'      from portal_intermediario',
'     where codusr  = :p2_codigo;',
'  exception',
'     when no_data_found then',
'          nExiste := 0;',
'  end;',
'  if nExiste = 1 then',
'     apex_error.add_error',
'            (p_message          => ''Productor ya se encuentra registrado.'',',
'             p_display_location => apex_error.c_inline_in_notification);',
'  end if;',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
