,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' l_body_html clob;',
' cServer VARCHAR2(60) := NULL;',
'begin ',
'',
' cServer := LOV (''SERVER'',''SERVER'',''PORTAL_SERVER'');',
'',
' l_body_html := ''',
'      <html lang="en-US">',
'        <head>',
'          <link rel="stylesheet" href="https://maxcdn.bootstrapcdn.com/font-awesome/4.5.0/css/font-awesome.min.css">',
'        </head>',
'        <body>',
'          <div style="height:300px; width:800px;border:1px solid rgb(167,162,162);box-shadow: 2px 2px 5px 2px rgb(216,204,203);">',
'            <div style="background:#244283; height:40px; width:800px;color:#fff;">',
unistr('               <h2 style="margin-left:20px; margin-top: 0px; padding-top: 10px;"> Verificaci\00F3n de Correo </h2>'),
'            </div>',
'            <div style="height: 45px;margin: 20px;">',
'            <p>',
'               <br>',
unistr('               Para culminar la activaci\00F3n de la cuenta, haga clic en el siguiente Link.</p>'),
'            <p><a href="''||cServer||''apex/f?p=&APP_ID.:8:::NO::P8_EMAIL:''||:p5_email_primario||''">Activar Cuenta</a></p><br>',
'            </div>',
'          </div>',
'        </body>',
'      </html>'';',
'                  ',
' send_mail_html (''info@singularpr.com '',',
'                  :p5_email,',
unistr('                  ''Portal de Clientes de Singular Agency - Verificaci\00F3n de Correo.'','),
'                  l_body_html);',
'                    ',
'exception',
'  when others then',
'       raise_application_error(-20100,sqlerrm);',
'end;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(61831870998701589)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_region_id=>wwv_flow_api.id(64210164052061576)
,p_process_type=>'NATIVE_FORM_DML'
,p_process_name=>'Process Create Form'
,p_attribute_01=>'PLSQL_CODE'
,p_attribute_04=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    case :APEX$ROW_STATUS',
'    when ''C'' then',
'        insert into portal_intermediario ',
'         ( codusr, password, email_primario, email_secundario,',
'           primer_nombre, segundo_nombre, primer_apellido,',
'           segundo_apellido, sexo, fecha_nacimiento, telefono_movil,',
'           telefono_oficina, dba_compania, direccion_postal,',
'           direccion_fisica, stsintermediario,',
'           nroint, is_verified, fecha_registro )',
'        values ',
'         ( :p5_codusr, pr_admin_intermediario.cifrar_clave(:p5_password), ',
'           :p5_email_primario,:p5_email_secundario,',
'           :p5_primer_nombre,:p5_segundo_nombre,:p5_primer_apellido,',
'           :p5_segundo_apellido,:p5_sexo,to_date(:p5_fecha_nacimiento,''MM/DD/YYYY''),:p5_telefono_movil,',
'           :p5_telefono_oficina,:p5_dba_compania,:p5_direccion_postal,',
'           :p5_direccion_fisica,''ACT'',0,''N'',sysdate);',
'    when ''U'' then',
'         null;',
'    when ''D'' then',
'         null;',
'    end case;',
'end;'))
,p_attribute_05=>'Y'
,p_attribute_06=>'Y'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(61855267613037130)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaData'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :p5_codusr is not null then',
'   begin',
'     select cp.capd_cacn_nu_cedula_rif,cp.capd_cacn_nu_cedula_rif,',
'            cc.cacn_primer_nombre, cc.cacn_segundo_nombre,',
'            cc.cacn_primer_apellido, cc.cacn_segundo_apellido,',
'            ce.cemc_email,cc.cacn_nm_apellido_razon,',
'            cc.cacn_fe_nacimiento',
'       into :p5_nacionalidad,:p5_cedula_rif, ',
'            :p5_primer_nombre,:p5_segundo_nombre,',
'            :p5_primer_apellido,:p5_segundo_apellido,',
'            :p5_email_primario,',
'            :p5_razon_social,',
'            :p5_fecha_nacimiento',
'       from cartera.cart_emails_cliente ce, cart_clientes cc, cart_productores cp',
'      where ce.cemc_cacn_nu_cedula_rif   = cc.cacn_nu_cedula_rif',
'        and ce.cemc_cacn_cd_nacionalidad = cc.cacn_cd_nacionalidad',
'        and cc.cacn_nu_cedula_rif        = cp.capd_cacn_nu_cedula_rif',
'        and cc.cacn_cd_nacionalidad      = cp.capd_cacn_cd_nacionalidad',
'        and cp.capd_cd_productor         = :p5_codusr;',
'   exception',
'      when no_data_found then',
'           :p5_nacionalidad     := null;',
'           :p5_cedula_rif       := null; ',
'           :p5_primer_nombre    := null;',
'           :p5_segundo_nombre   := null;',
'           :p5_primer_apellido  := null;',
'           :p5_segundo_apellido := null;',
'           :p5_email_primario   := null;',
'           :p5_razon_social     := null;',
'           :p5_fecha_nacimiento := null;',
'   end;',
'end if;',
'',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
