,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--noBorder:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51954354019191929)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
' select po.codprod||''-''||po.codofiemi||''-''||po.numpol nropoliza,',
'        ce.numcert,',
'        po.stspol Sts,',
'        te.apeter||'' ''||te.nomter Contratante,',
'        po.fecinivig,',
'        po.fecfinvig,   ',
'        po.fecemi,',
'        po.fecren,',
'        ti.apeter||'' ''||ti.nomter Productor,',
'        po.idepol,',
'        pr.busca_lval(''FORMPAGO'',po.codformpago) codformpago,',
'        pd.descprod,',
'        pr.busca_lval (''OFICINAS'', po.codofiemi)"OFICINA"',
'   from tercero ti, intermediario it, part_inter_pol pi, producto pd, tercero te, cliente cl, poliza_cia po, certificado ce',
'  where exists ( select 1 ',
'                   from recibo r ',
'                  where r.idepol = po.idepol ',
'                    and r.stsrec in (''ACT'', ''COB'')) ',
'    and trunc(sysdate) between trunc(po.fecinivig) and trunc(po.fecfinvig)',
'    and ti.tipoid    = it.tipoid',
'    and ti.numid     = it.numid',
'    and ti.dvid      = it.dvid',
'    and it.codinter  = pi.codinter',
'    and pi.indlider  = ''S''',
'    and pi.idepol    = po.idepol ',
'    and pd.codprod   = po.codprod',
'    and te.dvid      = cl.dvid',
'    and te.numid     = cl.numid',
'    and te.tipoid    = cl.tipoid',
'    and cl.codcli    = po.codcli',
'    and po.stspol in (''ACT'',''MOD'',''REN'')',
'    and po.idepol    = ce.idepol',
'    and ce.stscert   in (''ACT'',''MOD'',''REN'')',
'    and ce.codcli    = :A_CLIENTE'))
,p_plug_source_type=>'NATIVE_IG'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
