,p_name=>'Email Verification'
,p_step_title=>'Email Verification'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_page_is_public_y_n=>'Y'
,p_deep_linking=>'Y'
,p_last_updated_by=>'FPEREZ'
,p_last_upd_yyyymmddhh24miss=>'20231220111008'
);
wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(52465947983540454)
,p_plug_name=>unistr('Activar Cuenta del Cliente por Verificaci\00F3n de Correo')
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>wwv_flow_api.id(51954354019191929)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cEmail varchar2(100);',
'begin',
'  begin',
'    select email_primario',
'      into cEmail',
'      from portal_intermediario',
'     where email_primario = :p8_email;',
'  exception',
'     when too_many_rows then',
unistr('          raise_application_error(-20100,''Existe m\00E1s de un cliente con la cuenta de correo: ''||:p8_email);'),
'     when no_data_found then',
'          cEmail := null;',
'  end;',
'  ',
'  if cEmail is not null then',
'     update portal_intermediario',
'        set is_verified = ''S''',
'      where email_primario = :p8_email;',
'     ',
'     htp.p(''',
'            <style>',
'               .class1 {',
'                  text-align:center;',
'               } ',
'            </style>',
'           ',
'            <div style = "text-align:center;">',
'                 <h4>',
'                      Su cuenta de Correo Electronico ha sido verificado. </br>',
unistr('                      <a href="http://localhost:8080/ords/f?p=&APP_ID.:LOGIN_DESKTOP">Pulse Click</a>, para Abrir una Sesi\00F3n.'),
'                 </h4>',
'           ',
'           ',
'            </div>',
'     '');',
'  else',
'     htp.p(''',
'            <style>',
'               .class2 {',
'                  text-align:center;',
'               } ',
'            </style>',
'            <div class="class2">',
'                 <p>',
unistr('                     Opppss, hay un inconveniente con la verificaci\00F3n del Correo.'),
'                     Por favor, intentar en 30 minutos.  Si persiste el problema debe aperturar un ticket a la cuenta de Soporte.',
'                 </p>',
'            </div>',
'           ',
'     '');',
'  end if;',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
