,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Process Create Form'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update portal_empleado',
'    set email_primario   = :p9_email_primario, ',
'        primer_nombre    = :p9_primer_nombre, ',
'        segundo_nombre   = :p9_segundo_nombre, ',
'        primer_apellido  = :p9_primer_apellido,',
'        segundo_apellido = :p9_segundo_apellido, ',
'        sexo             = :p9_sexo, ',
'        fecha_nacimiento = TO_DATE(:p9_fecha_nacimiento,''MM/DD/YYYY''),',
'        telefono_movil   = :p9_telefono_movil,',
'        telefono_oficina = :p9_telefono_oficina',
'  where idempleado  = :p9_idempleado;'))
