wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(62064287603260496)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaData'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :p9_codusr is not null then',
'   begin',
'     select pi.email_primario,',
'            pi.primer_nombre, pi.segundo_nombre,',
'            pi.primer_apellido, pi.segundo_apellido,',
'            pi.sexo, ',
'            pi.fecha_nacimiento,',
'            pi.idempleado,',
'            pi.telefono_movil, pi.telefono_oficina',
'       into :p9_email_primario,',
'            :p9_primer_nombre,:p9_segundo_nombre,',
'            :p9_primer_apellido,:p9_segundo_apellido,',
'            :p9_sexo,',
'            :p9_fecha_nacimiento,',
'            :p9_idempleado,',
'            :p9_telefono_movil, :p9_telefono_oficina',
'       from portal_empleado pi',
'      where pi.codusr = :p9_codusr;',
'   exception',
'      when no_data_found then',
'            :p9_email_primario   := null;',
'            :p9_primer_nombre    := null;',
'            :p9_segundo_nombre   := null;',
'            :p9_primer_apellido  := null;',
'            :p9_segundo_apellido := null;',
'            :p9_sexo             := null;',
'            :p9_fecha_nacimiento := null;',
'            :p9_telefono_movil   := null;',
'            :p9_telefono_oficina := null;',
'   end;',
'end if;',
'',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
