,p_step_title=>unistr('P\00F3lizas Emitidas por Intermediario')
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_javascript_file_urls=>'#APP_IMAGES#crisp.js'
