wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(77161075223637859)
,p_plug_name=>unistr('P\00F3lizas Emitidas')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>10
,p_plug_grid_column_css_classes=>'hidden-xxs-down'
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cSql varchar2(4000);',
'begin',
' cSql := ''select cp.cacn_nm_apellido_razon NbreCia,',
'           fa.cjfc_nu_factura Factura, ',
'           fa.cjfc_nm_nombre_razon RazonSocial,',
'           ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'           fa.cjfc_nu_poliza NroPoliza, ',
'           pa.cjpc_fe_efectiva Fecha,',
'           rf.rv_meaning tpooperacion,',
'           PRIMA_NETA (fa.cjfc_cd_sucursal, fa.cjfc_nu_factura) Prima,',
'           pa.cjpc_mt_fees Fees,',
'           fa.cjfc_fecha FechaEmision,',
'           pr_admin_intermediario.display_name ( fa.cjfc_cd_productor ) nbreintermediario',
'      from cart_clientes cp,',
'           cajt_companias_externas co,',
'           cart_clientes cl, ',
'           cart_productores pr, ',
'           caja.cajt_payment_facturas pa, ',
'           cg_ref_codes rf,',
'           cajt_facturas_externas fa',
'     where cp.cacn_nu_cedula_rif   = co.cjce_cacn_nu_cedula_rif',
'       and cp.cacn_cd_nacionalidad = co.cjce_cacn_cd_nacionalidad',
'       and co.cjce_cd_compania     = pa.cjpc_cd_compania',
'       and cl.cacn_nu_cedula_rif   = pr.capd_cacn_nu_cedula_rif',
'       and cl.cacn_cd_nacionalidad = pr.capd_cacn_cd_nacionalidad',
'       and pr.capd_cd_productor    = fa.cjfc_cd_productor'';',
'',
' if :p14_tipo_fecha = ''F'' then',
'    cSql := cSql || '' and trunc(pa.cjpc_fe_efectiva) between to_date(:p14_desde,''''MM/DD/YYYY'''')',
'                                                         and to_date(:p14_hasta,''''MM/DD/YYYY'''')  '';',
' end if;',
'',
' if :p14_codcia = ''2'' then       -- Todas las Agencias.',
'     null;',
' elsif :p14_codcia = ''107'' then  -- Solo Western',
'    cSql := cSql ||'' and pa.cjpc_cd_compania = 107 '';',
' elsif :p14_codcia = ''1'' then    -- Solo Singular',
'    cSql := cSql ||'' and pa.cjpc_cd_compania <> 107 '';',
' end if;',
'',
' cSql := cSql || ',
'      '' and trunc(pa.cjpc_fe_efectiva) >= to_date(''''01/01/2023'''',''''MM/DD/YYYY'''')',
'        and pa.cjpc_cd_sucursal     = fa.cjfc_cd_sucursal',
'        and pa.cjpc_nu_factura      = fa.cjfc_nu_factura',
'        and pa.cjpc_nu_payment      = ( select max(de.cjpc_nu_payment)',
'                                          from cajt_payment_facturas de',
'                                         where de.cjpc_cd_sucursal = fa.cjfc_cd_sucursal',
'                                           and de.cjpc_nu_factura  = fa.cjfc_nu_factura )',
'        and rf.rv_low_value         = fa.cjfc_tp_operacion',
'        and rf.rv_domain            = ''''CAJA_FACTURAS_EXTERNAS_TP_OPERACION''''',
'        '';',
' ',
' if :p14_asegurado is not null then',
'    cSql := cSql || '' and fa.cjfc_nm_nombre_razon like ''''%''''||upper(:p14_asegurado)||''''%'''' '';',
' end if;',
' ',
' if :p14_poliza is not null then',
'    cSql := cSql || '' and fa.cjfc_nu_poliza = :p14_poliza '';',
' end if;',
' ',
'  if :p14_tipo_fecha = ''E'' then',
'    cSql := cSql || '' and fa.cjfc_fecha between to_date(:p14_desde,''''MM/DD/YYYY'''')',
'                                            and to_date(:p14_hasta,''''MM/DD/YYYY'''')  '';',
' end if;',
' ',
' if :p14_codinter is not null then',
'    cSql := cSql || '' and fa.cjfc_cd_productor = :p14_codinter '';',
' end if;',
' ',
' cSql := cSql ||',
'       '' and fa.cjfc_status_factura not in (3,7,8,9,10)',
'      order by cp.cacn_nm_apellido_razon,fa.cjfc_nu_poliza,fa.cjfc_nu_factura '';',
'',
' return cSql;',
'',
'end;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P14_DESDE,P14_HASTA,P14_ASEGURADO,P14_POLIZA,P14_TIPO_FECHA,P14_CODINTER,P14_CODCIA'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>8.5
,p_prn_height=>11
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
