 p_id=>wwv_flow_api.id(89561348408654703)
,p_plug_name=>unistr('P\00F3lizas Cobradas')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>10
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cSql LONG;',
'begin',
' cSql := '' select cp.cacn_nm_apellido_razon NbreCia, ',
'             fa.cjfc_nm_nombre_razon RazonSocial,',
'             fa.cjfc_nu_factura Factura, ',
'             ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'             fa.cjfc_nu_poliza NroPoliza, ',
'             pa.cjpc_fe_efectiva Fecha,',
'             rf.rv_meaning Operacion,',
'             MAX(PRIMA_NETA (fa.CJFC_CD_SUCURSAL, fa.cjfc_nu_factura)) Prima,',
'             MAX(CJPC_MT_FEES) Fees,',
'             fa.cjfc_abono Abono,',
'             max(op.cjod_fe_operacion) FechaCobro, ',
'             fa.cjfc_financiadora FinanciadoraDiferido,',
'             max(pr_admin_intermediario.display_name ( fa.cjfc_cd_productor )) nbreintermediario',
'        from cart_clientes cp, ',
'             cajt_companias_externas co,',
'             cart_clientes cl, ',
'             cart_productores pr, ',
'             cajt_operaciones_diarias_sng op, ',
'             caja.cajt_payment_facturas pa, ',
'             cg_ref_codes rf, ',
'             cajt_facturas_externas fa',
'       where cp.cacn_nu_cedula_rif     = co.cjce_cacn_nu_cedula_rif',
'         and cp.cacn_cd_nacionalidad   = co.cjce_cacn_cd_nacionalidad',
'         and co.cjce_cd_compania       = pa.cjpc_cd_compania',
'         and cl.cacn_nu_cedula_rif     = pr.capd_cacn_nu_cedula_rif',
'         and cl.cacn_cd_nacionalidad   = pr.capd_cacn_cd_nacionalidad',
'         and pr.capd_cd_productor      = fa.cjfc_cd_productor',
'         and op.cjod_cjto_cd_operacion = ''''2013''''',
'         and op.cjod_nu_recibo         = fa.cjfc_nu_factura '';',
'         ',
' if    :p16_codcia = 107 then',
'    cSql := cSql || '' and pa.cjpc_cd_compania = 107 '';',
' elsif :p16_codcia = 1   then',
'    cSql := cSql || '' and pa.cjpc_cd_compania <> 107 '';',
' end if;',
' ',
' cSql := cSql || ',
'       '' and pa.CJPC_NU_PAYMENT        = ( select MAX(de.CJPC_NU_PAYMENT)',
'                                             from cajt_payment_facturas de',
'                                            where de.CJPC_NU_FACTURA  = fa.cjfc_nu_factura',
'                                              and de.CJPC_CD_SUCURSAL = fa.CJFC_CD_SUCURSAL)',
'         and pa.cjpc_nu_factura        = fa.cjfc_nu_factura',
'         and rf.rv_low_value           = fa.cjfc_tp_operacion',
'         and rf.rv_domain              = ''''CAJA_FACTURAS_EXTERNAS_TP_OPERACION'''' '';',
'',
' if :p16_asegurado is not null then',
'    cSql := cSql || '' and fa.cjfc_nm_nombre_razon like ''''%''''||UPPER(:p16_asegurado)||''''%'''' '';',
' end if;',
' if :p16_poliza is not null then',
'    cSql := cSql || '' and fa.cjfc_nu_poliza   = UPPER(:p16_poliza) '';',
' end if;',
' ',
' if :p16_codinter is not null then',
'    cSql := cSql || '' and fa.cjfc_cd_productor = :p16_codinter '';',
' end if;',
' ',
' cSql := cSql || '' and fa.cjfc_status_factura in (4)',
'              group by cp.cacn_nm_apellido_razon,fa.cjfc_nu_factura, ',
'                       ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ),',
'                       fa.cjfc_nu_poliza,pa.cjpc_fe_efectiva,fa.cjfc_nm_nombre_razon,',
'                       pa.cjpc_mt_prima,fa.cjfc_abono,rf.rv_meaning,fa.cjfc_financiadora '';',
'                   ',
' if :p16_tipo_fecha = ''C'' then',
'    cSql := cSql || '' having max(op.cjod_fe_operacion) between to_date(:p16_desde,''''MM/DD/YYYY'''')',
'                                                           and to_date(:p16_hasta,''''MM/DD/YYYY'''') '';',
' end if;',
' ',
' if :p16_tipo_fecha = ''E'' then',
'    cSql := cSql || '' having pa.cjpc_fe_efectiva between to_date(:p16_desde,''''MM/DD/YYYY'''')',
'                                                     and to_date(:p16_hasta,''''MM/DD/YYYY'''') '';',
' end if;',
' ',
' return cSql;',
' ',
'end;'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P16_DESDE,P16_HASTA,P16_POLIZA,P16_ASEGURADO,P16_TIPO_FECHA,P16_CODINTER,P16_CODCIA'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>8.5
,p_prn_height=>11
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
