wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(101937562202276266)
,p_plug_name=>'Comisiones Pagadas'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>10
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cSql VARCHAR2(4000);',
'begin',
' cSql := '' select cp.cacn_nm_apellido_razon NbreCia, ',
'           fa.cjfc_nm_nombre_razon RazonSocial,',
'           fa.cjfc_nu_factura Factura, ',
'           ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ) StsFactura,',
'           fa.cjfc_nu_poliza NroPoliza, ',
'           pa.cjpc_fe_efectiva Fecha,       ',
'           rf.rv_meaning tpooperacion,',
'           MAX(PRIMA (fa.CJFC_CD_SUCURSAL, fa.cjfc_nu_factura)) Prima,',
'           sum(op.cjmp_mt_comision) MtoComision,',
'           CONCAT(TO_CHAR(MAX(fa.CJFC_PORC_COMISION), ''''fm999G999D00''''), ''''%'''') PORC_COMISION,',
'           max(op.cjmp_fe_movimiento) FechaPago,',
'           FECHA_PAG_COMISION (fa.cjfc_cd_sucursal, fa.cjfc_nu_factura) FechaPagoCom,',
'           MAX(pr_admin_intermediario.display_name ( fa.cjfc_cd_productor )) NbreIntermediario',
'      from cart_clientes cp, cajt_companias_externas co,',
'           cart_clientes cl, cart_productores pr, ',
'           cajt_movimientos_productores op, caja.cajt_payment_facturas pa, cg_ref_codes rf, ',
'           cajt_facturas_externas fa',
'     where cp.cacn_nu_cedula_rif     = co.cjce_cacn_nu_cedula_rif',
'       and cp.cacn_cd_nacionalidad   = co.cjce_cacn_cd_nacionalidad',
'       and co.cjce_cd_compania       = pa.cjpc_cd_compania',
'       and cl.cacn_nu_cedula_rif     = pr.capd_cacn_nu_cedula_rif',
'       and cl.cacn_cd_nacionalidad   = pr.capd_cacn_cd_nacionalidad',
'       and pr.capd_cd_productor      = fa.cjfc_cd_productor',
'       and op.cjmp_cjod_cd_operacion IN (2013, 5004, 7979)',
'       and op.cjmp_nu_recibo         = fa.cjfc_nu_factura '';',
' ',
' if    :p17_codcia = 107 then',
'    cSql := cSql || '' and pa.cjpc_cd_compania = 107 '';',
' elsif :p17_codcia = 1   then',
'    cSql := cSql || '' and pa.cjpc_cd_compania <> 107 '';',
' end if;',
'       ',
' cSql := cSql || ',
'    ''  and pa.cjpc_nu_factura        = fa.cjfc_nu_factura',
'       and rf.rv_low_value           = fa.cjfc_tp_operacion',
'       and rf.rv_domain              = ''''CAJA_FACTURAS_EXTERNAS_TP_OPERACION''''',
'       and fa.cjfc_status_factura in (4,5) '';',
'',
' if :p17_nropoliza is not null then',
'    cSql := cSql || '' and fa.cjfc_nu_poliza = UPPER(:p17_nropoliza) '';',
' end if;',
'',
' if :p17_razon_social is not null then',
'    cSql := cSql || '' and fa.cjfc_nm_nombre_razon like ''''%''''||UPPER(:p17_razon_social)||''''%'''' '';',
' end if;',
' ',
' if :p17_codinter is not null then',
'    cSql := cSql || '' and fa.cjfc_cd_productor = :p17_codinter '';',
' end if;',
'',
' cSql := cSql || '' and FECHA_PAG_COMISION (fa.cjfc_cd_sucursal, fa.cjfc_nu_factura) between to_date(:p17_desde,''''MM/DD/YYYY'''')',
'                                                                                        and to_date(:p17_hasta,''''MM/DD/YYYY'''')',
'                   group by cp.cacn_nm_apellido_razon, fa.cjfc_cd_sucursal, fa.cjfc_nu_factura, ',
'                            ESTATUS_FACTURA ( fa.cjfc_status_factura, ''''CAJA.CAJT_FACTURAS_EXTERNAS.CJFC_STATUS_FACTURA'''' ),',
'                            fa.cjfc_nu_poliza, ',
'                            pa.cjpc_fe_efectiva,fa.cjfc_nm_nombre_razon,pa.cjpc_mt_prima,rf.rv_meaning',
'                   order by FECHA_PAG_COMISION (fa.cjfc_cd_sucursal, fa.cjfc_nu_factura), fa.cjfc_nu_factura '';',
'                   ',
' return cSql;',
'end;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P17_DESDE,P17_HASTA,P17_NROPOLIZA,P17_RAZON_SOCIAL,P17_CODINTER,P17_CODCIA'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_document_header=>'APEX'
