wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(46346764298607112)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :p21_Id_Accidente IS NOT NULL THEN',
'',
'   -- Carga de los Datos del Propietario',
'   BEGIN',
'     SELECT Nombre, Apellido, Edad, Sexo, Email, Licencia, ',
'            Estado_Emi_Licencia,Seguro_Social, Direccion, Pueblo, ',
'            Codigo_Postal, Tlf_Residencia, Tlf_Trabajo,',
'            Cia_Seguros, Nro_Poliza',
'       INTO :p21_Nbre_Dueno,:p21_Apellido_Dueno,:p21_Edad,:p21_Sexo,:p21_Email,:p21_No_Licencia,',
'            :p21_Estado_Licencia,:p21_Nro_Social,:p21_Direccion,:p21_Pueblo,',
'            :p21_Codigo_postal,:p21_Telefono_Residencia,:p21_Telefono_Trabajo,',
'            :p21_Cia_Seguros,:p21_Nro_Poliza',
'       FROM AMI_ACC_PROPIETARIO',
'      WHERE Nro_Vehiculo = 1',
'        AND Id_Accidente = :p21_Id_Accidente;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p21_Nbre_Dueno          := NULL; :p21_Apellido_Dueno      := NULL;',
'           :p21_Edad                := NULL; :p21_Sexo                := NULL; ',
'           :p21_Email               := NULL; :p21_No_Licencia         := NULL; ',
'           :p21_Estado_Licencia     := NULL; :p21_Nro_Social          := NULL; ',
'           :p21_Direccion           := NULL; :p21_Pueblo              := NULL; ',
'           :p21_Codigo_postal       := NULL; :p21_Telefono_Residencia := NULL; ',
'           :p21_Telefono_Trabajo    := NULL; :p21_Cia_Seguros         := NULL; ',
'           :p21_Nro_Poliza          := NULL;',
'   END;',
'   ',
'   -- Carga del Conductor',
'   BEGIN',
'      SELECT Nombre,Apellido,Edad,Sexo,',
'             Licencia,Estado_Emi_Licencia,Seguro_Social,',
'             Direccion,Pueblo,Codigo_Postal,',
'             Tlf_Residencia,Tlf_Trabajo,',
'             Fecha_Marbete,Fecha_Venc_Marbete',
'        INTO :p21_Nbre_Conduc,:p21_Apellido_Conduc,:p21_Edad_Conduc,:p21_Sexo_Conduc,',
'             :p21_Nro_Licencia_Conduc,:p21_Edo_Lice_Conduc,:p21_Nro_Social_Conduc,',
'             :p21_Direc_Conduc,:p21_Pueblo_Conduc,:p21_Cod_Postal_Conduc,',
'             :p21_Tlf_Reside_Conductor,:p21_Tlf_Traba_Conductor,',
'             :p21_Fecha_Marbete,:p21_Fecha_Venc_Marbete',
'        FROM AMI_ACC_CONDUCTOR',
'       WHERE Nro_Vehiculo = 1',
'         AND Id_Accidente = :p21_Id_Accidente;',
'   EXCEPTION',
'       WHEN NO_DATA_FOUND THEN',
'             :p21_Nbre_Conduc          := NULL;  :p21_Apellido_Conduc     := NULL;',
'             :p21_Edad_Conduc          := NULL;  :p21_Sexo_Conduc         := NULL;',
'             :p21_Nro_Licencia_Conduc  := NULL;  :p21_Edo_Lice_Conduc     := NULL;',
'             :p21_Nro_Social_Conduc    := NULL;  :p21_Direc_Conduc        := NULL;',
'             :p21_Pueblo_Conduc        := NULL;  :p21_Cod_Postal_Conduc   := NULL;',
'             :p21_Tlf_Reside_Conductor := NULL;  :p21_Tlf_Traba_Conductor := NULL;',
'             :p21_Fecha_Marbete        := NULL;  :p21_Fecha_Venc_Marbete  := NULL;',
'   END;',
'   ',
'   -- Carga de los Datos del Vehiculo',
'   BEGIN',
'     SELECT MarcaVeh,ModeloVeh,AnoVeh,ColorVeh,Tablilla,',
'            Millaje,NroVin,NroRegistro,Observa',
'       INTO :p21_Marca_Veh,:p21_Modelo_Veh,:p21_Anual_Veh,:p21_Color_Veh,:p21_Tablilla_Veh,',
'            :p21_Millaje_Veh,:p21_Nro_Motor_Veh,:p21_Nro_Registro,:p21_Comentario',
'       FROM AMI_ACC_VEHICULO',
'      WHERE  Nro_Vehiculo = 1',
'        AND Id_Accidente = :p21_Id_Accidente; ',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p21_Marca_Veh     := NULL; :p21_Modelo_Veh   := NULL;',
'           :p21_Anual_Veh     := NULL; :p21_Color_Veh    := NULL;',
'           :p21_Tablilla_Veh  := NULL; :p21_Millaje_Veh  := NULL;',
'           :p21_Nro_Motor_Veh := NULL; :p21_Nro_Registro := NULL;',
'           :p21_Comentario    := NULL;',
'   END;',
'',
'END IF;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
