wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(46390855147603618)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :p21_Id_Accidente IS NOT NULL THEN',
'',
'   -- Carga de los Datos del Propietario',
'   BEGIN',
'     SELECT Nombre, Apellido, Edad, Sexo, Email, Licencia, ',
'            Estado_Emi_Licencia,Seguro_Social, Direccion, Pueblo, ',
'            Codigo_Postal, Tlf_Residencia, Tlf_Trabajo,',
'            Cia_Seguros, Nro_Poliza',
'       INTO :p22_Nbre_Dueno,:p22_Apellido_Dueno,:p22_Edad,:p22_Sexo,:p22_Email,:p22_No_Licencia,',
'            :p22_Estado_Licencia,:p22_Nro_Social,:p22_Direccion,:p22_Pueblo,',
'            :p22_Codigo_postal,:p22_Telefono_Residencia,:p22_Telefono_Trabajo,',
'            :p22_Cia_Seguros,:p22_Nro_Poliza',
'       FROM AMI_ACC_PROPIETARIO',
'      WHERE Nro_Vehiculo = 2',
'        AND Id_Accidente = :p22_Id_Accidente;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p22_Nbre_Dueno          := NULL; :p22_Apellido_Dueno      := NULL;',
'           :p22_Edad                := NULL; :p22_Sexo                := NULL; ',
'           :p22_Email               := NULL; :p22_No_Licencia         := NULL; ',
'           :p22_Estado_Licencia     := NULL; :p22_Nro_Social          := NULL; ',
'           :p22_Direccion           := NULL; :p22_Pueblo              := NULL; ',
'           :p22_Codigo_postal       := NULL; :p22_Telefono_Residencia := NULL; ',
'           :p22_Telefono_Trabajo    := NULL; :p22_Cia_Seguros         := NULL; ',
'           :p22_Nro_Poliza          := NULL;',
'   END;',
'   ',
'   -- Carga del Conductor',
'   BEGIN',
'      SELECT Nombre,Apellido,Edad,Sexo,',
'             Licencia,Estado_Emi_Licencia,Seguro_Social,',
'             Direccion,Pueblo,Codigo_Postal,',
'             Tlf_Residencia,Tlf_Trabajo,',
'             Fecha_Marbete, Fecha_Venc_Marbete',
'        INTO :p22_Nbre_Conduc,:p22_Apellido_Conduc,:p22_Edad_Conduc,:p22_Sexo_Conduc,',
'             :p22_Nro_Licencia_Conduc,:p22_Edo_Lice_Conduc,:p22_Nro_Social_Conduc,',
'             :p22_Direc_Conduc,:p22_Pueblo_Conduc,:p22_Cod_Postal_Conduc,',
'             :p22_Tlf_Reside_Conductor,:p22_Tlf_Traba_Conductor,',
'             :p22_Fecha_Marbete,:p22_Fecha_Venc_Marbete',
'        FROM AMI_ACC_CONDUCTOR',
'       WHERE Nro_Vehiculo = 2',
'         AND Id_Accidente = :p22_Id_Accidente;',
'   EXCEPTION',
'       WHEN NO_DATA_FOUND THEN',
'             :p22_Nbre_Conduc          := NULL;  :p22_Apellido_Conduc     := NULL;',
'             :p22_Edad_Conduc          := NULL;  :p22_Sexo_Conduc         := NULL;',
'             :p22_Nro_Licencia_Conduc  := NULL;  :p22_Edo_Lice_Conduc     := NULL;',
'             :p22_Nro_Social_Conduc    := NULL;  :p22_Direc_Conduc        := NULL;',
'             :p22_Pueblo_Conduc        := NULL;  :p22_Cod_Postal_Conduc   := NULL;',
'             :p22_Tlf_Reside_Conductor := NULL;  :p22_Tlf_Traba_Conductor := NULL;',
'             :p22_Fecha_Marbete        := NULL;  :p22_Fecha_Venc_Marbete  := NULL;',
'   END;',
'   ',
'   -- Carga de los Datos del Vehiculo',
'   BEGIN',
'     SELECT MarcaVeh,ModeloVeh,AnoVeh,ColorVeh,Tablilla,',
'            Millaje,NroVin,NroRegistro,Observa',
'       INTO :p22_Marca_Veh,:p22_Modelo_Veh,:p22_Anual_Veh,:p22_Color_Veh,:p22_Tablilla_Veh,',
'            :p22_Millaje_Veh,:p22_Nro_Motor_Veh,:p22_Nro_Registro,:p22_Comentario',
'       FROM AMI_ACC_VEHICULO',
'      WHERE  Nro_Vehiculo = 2',
'        AND Id_Accidente = :p22_Id_Accidente; ',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p22_Marca_Veh     := NULL; :p22_Modelo_Veh   := NULL;',
'           :p22_Anual_Veh     := NULL; :p22_Color_Veh    := NULL;',
'           :p22_Tablilla_Veh  := NULL; :p22_Millaje_Veh  := NULL;',
'           :p22_Nro_Motor_Veh := NULL; :p22_Nro_Registro := NULL;',
'           :p22_Comentario    := NULL;',
'   END;',
'',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
