,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :p23_id_accidente is not null then',
' begin',
'   select confirma',
'     into :p23_acepto',
'     from ami_acc_accidente',
'    where id_accidente = :p23_id_accidente;',
' exception',
'    when others then ',
'         :p23_acepto := ''N'';',
' end;',
'end if;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
