wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(64483507373620964)
,p_plug_name=>'Cartera de Renovaciones Reporte'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
' cSQL long;',
'begin',
' cSQL := ''select  distinct cl.cacn_nm_apellido_razon NbreCia, fa.cjfc_cd_sucursal, fa.cjfc_nu_poliza, fa.cjfc_nac_cliente, ',
'                   fa.cjfc_nu_cliente, fa.cjfc_nm_nombre_razon, rc.rv_meaning, pf.cjpc_fe_efectiva, pf.cjpc_fec_vencimiento,',
'                   prima (fa.cjfc_cd_sucursal, fa.cjfc_nu_factura) Prima,',
'                   CASE POLIZA_RENOVADA (fa.cjfc_nu_poliza, pf.cjpc_fec_vencimiento) ',
'                            WHEN ''''S'''' THEN ''''Renovada''''',
'                            WHEN ''''N'''' THEN ''''No Renovada''''',
'                   END as EstatusRenovacion,',
'                   fa.cjfc_caac_cd_ramo_externo CodigoRamo,',
'                   RAMO (fa.cjfc_caac_cd_ramo_externo) DescRamo,',
'                   ESTATUS_POLIZA_RENOVADA (fa.cjfc_nu_poliza, pf.cjpc_fec_vencimiento) StsPolizaRenovada,',
'                   pr_admin_intermediario.display_name ( fa.cjfc_cd_productor ) nbreintermediario',
'              from cart_clientes cl, ',
'                   cajt_companias_externas co, ',
'                   cg_ref_codes rc, ',
'                   cajt_payment_facturas pf, ',
'                   cajt_facturas_externas fa',
'             where cl.cacn_nu_cedula_rif   = co.cjce_cacn_nu_cedula_rif',
'               and cl.cacn_cd_nacionalidad = co.cjce_cacn_cd_nacionalidad',
'               and co.cjce_cd_compania     = pf.cjpc_cd_compania',
'               and rc.rv_low_value = fa.cjfc_tp_operacion',
'               and rc.rv_domain    = ''''CAJA_FACTURAS_EXTERNAS_TP_OPERACION'''' '';',
'',
' if :p24_codcia = 107 then',
'     cSQL := cSQL || '' and pf.cjpc_cd_compania = 107 '';',
' elsif :p24_codcia =   1 then',
'     cSQL := cSQL || '' and pf.cjpc_cd_compania <> 107 '';',
' end if;',
'      ',
' cSQL := cSQL ',
'          || '' and pf.cjpc_nu_payment  = ( select max(ma.cjpc_nu_payment)',
'                                             from cajt_payment_facturas ma',
'                                            where ma.cjpc_fec_vencimiento between to_date(:p24_desde,''''MM/DD/YYYY'''') ',
'                                                                              and to_date(:p24_hasta,''''MM/DD/YYYY'''')',
'                                              and ma.cjpc_cd_sucursal = pf.cjpc_cd_sucursal',
'                                              and ma.cjpc_nu_factura  = pf.cjpc_nu_factura )',
'               and pf.cjpc_cd_sucursal      = fa.cjfc_cd_sucursal ',
'               and pf.cjpc_nu_factura       = fa.cjfc_nu_factura',
'               and fa.CJFC_STATUS_FACTURA   = 4   -- indicado por Jose Manuel',
'               and fa.cjfc_nm_nombre_razon like nvl(''''%''''||UPPER(:p24_asegurado)||''''%'''',fa.cjfc_nm_nombre_razon)',
'               and fa.cjfc_nu_poliza    = nvl(:p24_poliza,fa.cjfc_nu_poliza)',
'               and fa.cjfc_nu_poliza    not like ''''58PR%'''' ',
'               and fa.cjfc_tp_operacion in (''''1'''',''''3'''')',
'               and fa.cjfc_cd_productor = NVL(:p24_codinter,fa.cjfc_cd_productor)',
'               order by pf.cjpc_fec_vencimiento,fa.cjfc_nm_nombre_razon '';',
'',
' return cSQL;',
'end;',
'',
'',
'',
'',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P24_DESDE,P24_HASTA,P24_ASEGURADO,P24_POLIZA,P24_CODINTER,P24_CODCIA'
