wwv_flow_api.create_page_plug(
 p_id=>wwv_flow_api.id(77782023982901176)
,p_plug_name=>'Movimientos de Productores Reporte'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>50
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  SELECT   B.CJFC_NU_POLIZA  POLIZA,',
'         B.CJFC_NU_FACTURA FACTURA,',
'         A.CJMP_CAPD_CD_PRODUC PRODUCTOR,',
'         E.CACN_NM_APELLIDO_RAZON NOMBRE,',
'         B.CJFC_CAAC_CD_RAMO_EXTERNO RAMO,',
'         MAX (B.CJFC_MT_TOTAL) PRIMA,  ',
'         SUM (C.CJPC_MT_PRIMA) PRIMA_NETA,',
'         C.CJPC_MT_FEES FEES,',
'         --MAX(B.CJFC_PORC_COMISION) PORC_COMISION,',
'         CONCAT(TO_CHAR(MAX(B.CJFC_PORC_COMISION), ''fm999G999D00''), ''%'') PORC_COMISION,',
'         BUSCA_TIPO_OPERACION (A.CJMP_CJOD_CD_OPERACION) TIPO_OPERACION,  ',
'         F.CJEG_FE_GRABACION  FECHA_GRABACION,',
'         SUM (A.CJMP_MT_COMISION) COMISION',
'    FROM CAJT_PAYMENT_FACTURAS C,  CAJT_FACTURAS_EXTERNAS B, CART_CLIENTES E, CART_PRODUCTORES D, ',
'         CAJT_MOVIMIENTOS_PRODUCTORES A, CAJT_EGRESOS F',
'   WHERE C.CJPC_NU_FACTURA           = B.CJFC_NU_FACTURA      ',
'     AND B.CJFC_NU_FACTURA           = A.CJMP_NU_RECIBO',
'     AND B.CJFC_CD_SUCURSAL          = A.CJMP_CASU_CD_SUCURSAL',
'     AND E.CACN_CD_NACIONALIDAD      = D.CAPD_CACN_CD_NACIONALIDAD ',
'     AND E.CACN_NU_CEDULA_RIF        = D.CAPD_CACN_NU_CEDULA_RIF',
'     AND D.CAPD_CD_PRODUCTOR         = A.CJMP_CAPD_CD_PRODUC',
'     AND A.CJMP_CAPD_CD_PRODUC       = :A_CODINTER',
'     AND A.CJMP_CJEG_NU_EGRESO       = F.CJEG_NU_EGRESO',
'     AND A.CJMP_CJCM_CD_COMPANIA     = F.CJEG_CJCM_CD_COMPANIA     ',
'     AND A.CJMP_CASU_CD_SUCURSAL     = F.CJEG_CASU_CD_SUCURSAL',
'     AND F.CJEG_FE_GRABACION         BETWEEN to_date(:p25_desde,''MM/DD/YYYY'') and to_date(:p25_hasta,''MM/DD/YYYY'')',
'     AND F.CJEG_CJCM_CD_COMPANIA     = 3        ',
'   GROUP BY A.CJMP_CAPD_CD_PRODUC,E.CACN_NM_APELLIDO_RAZON,',
'            A.CJMP_CJEG_NU_EGRESO,B.CJFC_NU_POLIZA,',
'            B.CJFC_NU_FACTURA,B.CJFC_CAAC_CD_RAMO_EXTERNO,',
'            C.CJPC_MT_FEES,A.CJMP_CJOD_CD_OPERACION,',
'            F.CJEG_FE_GRABACION',
'   ORDER BY CJMP_CAPD_CD_PRODUC;',
''))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P25_DESDE,P25_HASTA'
