,p_validation_name=>'Get_Email'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'  cEmail PORTAL_INTERMEDIARIO.Email_Primario%TYPE;',
'BEGIN',
'',
' BEGIN',
'   SELECT Email_Primario',
'     INTO cEmail',
'     FROM PORTAL_INTERMEDIARIO',
'    WHERE Email_Primario = :p26_Email;',
'    RETURN TRUE;',
' EXCEPTION',
'    WHEN OTHERS THEN',
'         RETURN FALSE;',
' END; ',
'',
'END;'))
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Problemas con la cuenta de correo.'
,p_associated_item=>wwv_flow_api.id(47648015522372319)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(47648224585372321)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Send Email'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
' l_body_html   CLOB;',
' cEmail        VARCHAR2 (50);',
' cServer       VARCHAR2 (60);',
'BEGIN',
'',
' SELECT Email_Primario',
'   INTO cEmail',
'   FROM PORTAL_INTERMEDIARIO',
'  WHERE Email_Primario = :P26_EMAIL;',
'  ',
' cServer := LOV (''SERVER'',''SERVER'',''PORTAL_SERVER'');',
'  ',
' l_body_html := ''<body>',
'                  <div style="height:300px;  margin-left: 15px; width: 100%;border: 1px solid rgb(167, 162, 162);box-shadow: 2px 2px 5px 2px rgb(216, 204, 203);">',
'                    <div style="background:#244283; height: 40px; width: 100%;color:#fff;">',
unistr('                      <h2 style="margin-left:20px; margin-top: 0px; padding-top: 10px;">Verificaci\00F3n del Correo</div>'),
'                    </div>',
'                    <div style="height: 45px;margin: 20px;">',
'                      <p>Recover your password.<br /> Para verificar su cuenta, haga click en el siguiente Link:</p>''||',
'                      ''<p><a href="''||cServer||''apex/f?p=&APP_ID.:30:::NO::P30_EMAIL:''||:P26_email||''">Activar Cuenta</a></p>''||',
'                      ''<b> Verificado su cuenta. </b></a></p><br />',
'                    </div>',
'                  </div>',
'                 </body>'';',
'                 ',
'  /*               ',
'  <p><a href="http://10.200.10.32:8585/apex/f?p=&APP_ID.:8:::NO::P8_EMAIL:''||:p5_email_primario||''">Activar Cuenta</a></p><br>',
'  APEX_MAIL.SEND ( :P26_EMAIL,',
'                    ''no-reply@oraclelearner.com'',',
'                    l_body_html,',
'                    l_body_html,',
'                    ''Account Verification Email'',',
'                    NULL,',
'                    NULL,',
'                    NULL);',
'  */',
'  send_mail_html (''info@singularpr.com '',',
'                  :P26_EMAIL,',
unistr('                  ''Portal de Clientes de Singular Agency - Verificaci\00F3n de Cuenta.'','),
'                  l_body_html);',
'EXCEPTION',
'   WHEN OTHERS THEN',
'        NULL;',
'END;',
'               '))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_api.id(47648360388372322)
);
end;
