 p_id=>wwv_flow_api.id(64068489172573546)
,p_plug_name=>'Report 1'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_api.id(51953280910191929)
,p_plug_display_sequence=>10
,p_plug_display_point=>'BODY'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT sisi_casu_cd_sucursal SUCURSAL,',
'           sisi_nu_siniestro NRO_RECLAMO,',
'           sisi_fe_declaracion FECHA_DECLARACION,',
'           sisi_fe_ocurrencia FECHA_OCURRENCIA,',
'           SISI_CACN_CD_NACIONALIDAD || ''-'' || SISI_CACN_NU_CEDULA_RIF CLIENTE,',
'           A1.CACN_NM_APELLIDO_RAZON NOMBRE_CLIENTE,',
'           SISI_SITP_CD_TIPO_SINIESTRO TIPO_SINIESTRO,',
'           SISI_SICS_CD_CAUSA_SINIESTRO CAUSA_SINIESTRO,',
'           sice_care_casu_cd_sucursal SUCURSAL_RECIBO,',
'           sice_care_nu_recibo NUMERO_RECIBO,',
'           sisi_st_siniestro ESTATUS_SINIESTRO,',
'           sisi_de_rechazo DESC_RECHAZO_SINIESTRO,',
'           sice_cace_casu_cd_sucursal || ''-'' || sice_cace_carp_cd_ramo || ''-'' || sice_cace_carp_cd_ramo || ''-'' || sice_cace_capo_nu_poliza POLIZA,',
'           sice_cace_nu_certificado NUMERO_CERTIFICADO,',
'           SICE_CD_BIEN_ASEG BIEN_ASEGURADO,',
'           SICE_FE_COBERTURA FECHA_CUBIERTA,',
'           caps_cd_proveedor         CODIGO_AJUSTADOR,',
'           A2.cacn_nm_apellido_razon NOMBRE_AJUSTADOR',
'      FROM sint_siniestros,',
'           sint_certificados_siniestros,',
'           Cartera.Cart_clientes A1,',
'           cart_proveedores_servicios,',
'           Cartera.cart_clientes A2',
'     WHERE sisi_casu_cd_sucursal = 1',
'           AND sisi_nu_siniestro = 102198',
'           AND sice_sisi_casu_cd_sucursal = sisi_casu_cd_sucursal',
'           AND sice_sisi_nu_siniestro = sisi_nu_siniestro',
'           AND SISI_CACN_CD_NACIONALIDAD = A1.CACN_CD_NACIONALIDAD',
'           AND SISI_CACN_NU_CEDULA_RIF   = A1.CACN_NU_CEDULA_RIF',
'           And CAPS_CACN_CD_NACIONALIDAD = A2.CACN_CD_NACIONALIDAD',
'           And CAPS_CACN_NU_CEDULA_RIF   = A2.CACN_NU_CEDULA_RIF',
'           And SISI_CAPS_CD_PROVEEDOR    = CAPS_CD_PROVEEDOR'))
,p_plug_source_type=>'NATIVE_IR'
);
