,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'   SELECT  CJEG_NU_EGRESO,',
'           CJEG_FE_STATUS,',
'           CJEG_NM_BENEFICIARIO,',
'           CJEG_MT_GASTO,',
'           CJCH_NU_CHEQUE,',
'           CJCH_FE_EMISION,',
'           CJCH_ST_CHEQUE,',
'           substr(RV_MEANING,1,21) desc_estatus_cheque,',
'           CJCH_FE_STATUS,',
'           SIME_MT_PAGO',
'      FROM SINT_MOVIMIENTOS_EGRESOS,',
'           SINT_LIQUIDACIONES,',
'           SINT_SINIESTROS,',
'           CAJT_CHEQUES,',
'           CG_REF_CODES,',
'           CAJT_EGRESOS',
'    WHERE SISI_CASU_CD_SUCURSAL = :P28_SUCURSAL',
'      And SISI_NU_SINIESTRO = :P28_NRO_RECLAMO',
'      And SISI_CASU_CD_SUCURSAL = SILI_SISI_CASU_CD_SUCURSAL',
'      and SISI_NU_SINIESTRO     = SILI_SISI_NU_SINIESTRO',
'      And SILI_NU_LIQUIDACION   = SIME_SILI_NU_LIQUIDACION',
'      And SIME_SISI_CASU_CD_SUCURSAL = SILI_SISI_CASU_CD_SUCURSAL',
'      And SIME_SISI_NU_SINIESTRO     = SILI_SISI_NU_SINIESTRO',
'      AND CJEG_CJTE_CD_EGRESO        = 700',
'      And CJEG_NU_EGRESO             = CJCH_CJEG_NU_EGRESO',
'      And SILI_CJEG_NU_EGRESO        = CJEG_NU_EGRESO',
'      And RV_DOMAIN = ''CAJT_EGRESOS.CJEG_ST_EGRESO''',
'      AND substr(RV_LOW_VALUE,1,2) = CJEG_ST_EGRESO',
'      ',
''))
,p_ajax_enabled=>'Y'
,p_query_row_template=>wwv_flow_api.id(51974615721191940)
