wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(46468983322228973)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Carga'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
' BEGIN',
'  IF :p32_Id_Catastrofe IS NOT NULL THEN',
'   BEGIN',
'     SELECT FechaIncidente,HoraIncidente,TpoIncidente,PropiedadAsegurada,',
'            PropiedadDireccion,DescIncidente,VehiculoAfectado,',
'            MarcaVehiculo,ModeloVehiculo,',
'            AnoVehiculo,TabVehiculo,VinVehiculo,DescDanoVeh',
'       INTO :p32_Fecha_Incidente,:p32_Hora,:p32_Tipo_De_Incidente,:p32_Propiedad_Asegurada,',
'            :p32_Direccion_Fisica,:p32_Descripcion_De_Los_Danos,:p32_Vehiculo_Afectado,',
'            :p32_Marca_Veh,:p32_Modelo_Veh,',
'            :p32_Anual_Veh,:p32_Tablilla_Veh,:p32_Nro_Motor_Veh,:p32_Comentario',
'       FROM INCIDENTE_CATASTROFE',
'      WHERE Id_Catastrofe  = :p32_Id_Catastrofe;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'            :p32_Fecha_Incidente          := NULL;',
'            :p32_Hora                     := NULL;',
'            :p32_Tipo_De_Incidente        := NULL;',
'            :p32_Propiedad_Asegurada      := NULL;',
'            :p32_Direccion_Fisica         := NULL;',
'            :p32_Descripcion_De_Los_Danos := NULL;',
'            :p32_Vehiculo_Afectado        := NULL;',
'            :p32_Marca_Veh                := NULL;',
'            :p32_Modelo_Veh               := NULL;',
'            :p32_Anual_Veh                := NULL;',
'            :p32_Tablilla_Veh             := NULL;',
'            :p32_Nro_Motor_Veh            := NULL;',
'            :p32_Comentario               := NULL;',
'   END;',
' END IF;',
'END;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
