'.carousel {',
'    position: relative;',
'    width: 600px; /* Ancho del carrusel */',
'    overflow: hidden; /* Oculta el contenido que se sale del contenedor */',
unistr('    margin: auto; /* Centra el carrusel en la p\00E1gina */'),
'}',
'',
'.carousel-inner {',
'    display: flex; /* Usar flexbox para alinear los elementos horizontalmente */',
unistr('    transition: transform 0.5s ease; /* Transici\00F3n suave */'),
'}',
'',
'.carousel-item {',
'    min-width: 100%; /* Cada item ocupa el ancho completo del carrusel */',
'}',
'',
'.carousel img {',
unistr('    width: 100%; /* Las im\00E1genes ocupan todo el ancho del item */'),
unistr('    height: auto; /* Mantiene la proporci\00F3n de las im\00E1genes */'),
'}',
'',
'.prev, .next {',
'    position: absolute;',
'    top: 50%;',
'    transform: translateY(-50%);',
'    background-color: rgba(255, 255, 255, 0.5); /* Fondo semi-transparente */',
'    border: none;',
'    padding: 10px;',
'    cursor: pointer;',
'}',
'',
'.prev {',
unistr('    left: 10px; /* Posici\00F3n del bot\00F3n anterior */'),
'}',
'',
'.next {',
unistr('    right: 10px; /* Posici\00F3n del bot\00F3n siguiente */'),
'}'))
