wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(46535930856178256)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :p42_Id_Resp_Publica IS NOT NULL THEN',
'  BEGIN',
'     SELECT FechaIncidente, HoraIncidente, TpoIncidente, Lugar,',
'            DescIncidente, NotifaAutoridad, EmergenciaMedica, VehiculoAfectado,',
'            MarcaVehiculo, ModeloVehiculo, AnoVehiculo, TabVehiculo,',
'            VinVehiculo, DescDanoVeh',
'       INTO :p42_Fecha_Incidente, :p42_Hora, :p42_Tipo_De_Incidente, :p42_Lugar,',
'            :p42_Descripcion_De_Los_Danos, :p42_Autoridades, :p42_Emergencias, :p42_Vehiculo_Afectado,',
'            :p42_Marca_Veh, :p42_Modelo_Veh, :p42_Anual_Veh, :p42_Tablilla_Veh,',
'            :p42_Nro_Motor_Veh, :p42_Comentario',
'       FROM INCIDENTE_RESP_PUBLICA',
'      WHERE  Id_Resp_Publica = :p42_Id_Resp_Publica;',
'  EXCEPTION',
'      WHEN NO_DATA_FOUND THEN ',
'           :p42_Fecha_Incidente          := NULL; :p42_Hora              := NULL; ',
'           :p42_Tipo_De_Incidente        := NULL; :p42_Lugar             := NULL;',
'           :p42_Descripcion_De_Los_Danos := NULL; :p42_Autoridades       := NULL;',
'           :p42_Emergencias              := NULL; :p42_Vehiculo_Afectado := NULL;',
'           :p42_Marca_Veh                := NULL; :p42_Modelo_Veh        := NULL;',
'           :p42_Anual_Veh                := NULL; :p42_Tablilla_Veh      := NULL;',
'           :p42_Nro_Motor_Veh            := NULL; :p42_Comentario        := NULL;',
'  END;',
'ELSE',
'  :p42_Fecha_Incidente          := NULL; :p42_Hora              := NULL; ',
'  :p42_Tipo_De_Incidente        := NULL; :p42_Lugar             := NULL;',
'  :p42_Descripcion_De_Los_Danos := NULL; :p42_Autoridades       := NULL;',
'  :p42_Emergencias              := NULL; :p42_Vehiculo_Afectado := NULL;',
'  :p42_Marca_Veh                := NULL; :p42_Modelo_Veh        := NULL;',
'  :p42_Anual_Veh                := NULL; :p42_Tablilla_Veh      := NULL;',
'  :p42_Nro_Motor_Veh            := NULL; :p42_Comentario        := NULL;',
'END IF;',
''))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
