wwv_flow_api.create_page_process(
 p_id=>wwv_flow_api.id(46598478700140889)
,p_process_sequence=>10
,p_process_point=>'BEFORE_BOX_BODY'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'CargaDatos'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'IF :P52_Id_Perdida IS NOT NULL THEN',
'   BEGIN',
'     SELECT FechaIncidente,HoraIncidente,TpoIncidente,ReportadoPolicia,',
'            NroQuerella,NbrePolicia,NroPlaca,LugarPerdida,DescPerdida',
'       INTO :p52_Fecha_Perdida,:p52_Hora_Perdida,:p52_Tpo_Perdida,:p52_Reportado,',
'            :p52_Nro_Querella,:p52_Nbre_Policia,:p52_Placa_Policia,:p52_Lugar_Perdida,:p52_Detalles',
'       FROM INCIDENTE_PERDIDA_PROPIEDAD',
'      WHERE Id_Perdida_Propiedad = :p52_Id_Perdida;',
'   EXCEPTION',
'      WHEN NO_DATA_FOUND THEN',
'           :p52_Fecha_Perdida := NULL;',
'           :p52_Hora_Perdida  := NULL;',
'           :p52_Tpo_Perdida   := NULL;',
'           :p52_Reportado     := NULL;',
'           :p52_Nro_Querella  := NULL;',
'           :p52_Nbre_Policia  := NULL;',
'           :p52_Placa_Policia := NULL;',
'           :p52_Lugar_Perdida := NULL;',
'           :p52_Detalles      := NULL;',
'   END;',
'ELSE',
'   :p52_Fecha_Perdida := NULL;',
'   :p52_Hora_Perdida  := NULL;',
'   :p52_Tpo_Perdida   := NULL;',
'   :p52_Reportado     := NULL;',
'   :p52_Nro_Querella  := NULL;',
'   :p52_Nbre_Policia  := NULL;',
'   :p52_Placa_Policia := NULL;',
'   :p52_Lugar_Perdida := NULL;',
'   :p52_Detalles      := NULL;',
'END IF;'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
);
end;
