'@media (max-width: 1150px) {',
'  .home-content .sales-boxes{',
'    flex-direction: COLUMN;',
'  }',
'  .home-content .sales-boxes .box{',
'    width: 100%;',
'    OVERFLOW-x: scroll;',
'    margin-bottom: 30px;',
'  }',
'  .home-content .sales-boxes .top-sales{',
'    margin: 0;',
'  }',
'}',
'@media (max-width: 1000px) {',
'  .overview-boxes .box{',
'    width: calc(100% / 2 - 15px);',
'    margin-bottom: 15px;',
'  }',
'}',
'@media (max-width: 700px) {',
'  nav .sidebar-button .dashboard,',
'  nav .PROFILE-details .admin_name,',
'  nav .PROFILE-details i{',
'    display: NONE;',
'  }',
'  .home-section nav .PROFILE-details{',
'    height: 50px;',
'    MIN-width: 40px;',
'  }',
'  .home-content .sales-boxes .sales-details{',
'    width: 560px;',
'  }',
'}',
'@media (max-width: 550px) {',
'  .overview-boxes .box{',
'    width: 100%;',
'    margin-bottom: 15px;',
'  }',
'  .sidebar.ACTIVE ~ .home-section nav .PROFILE-details{',
'    display: NONE;',
'  }',
'}',
'',
'</style>'');',
'HTP.P(''<body>'');',
'',
'',
'FOR u IN ( select   ( select 978',
'                        from dual',
'                       ',
'                       ) as Clientes_Activos,',
'                    ( select to_char(4560,''999,999,999,999.99'')',
'                        from dual',
'                         ) as Comisiones_Pendientes,',
'                    ( select 90',
'                        from dual) as Polizas_Activas,',
'                    ( select 562 ',
'                        from dual',
'                         ) as Polizas_Renovar                  ',
'            from dual )',
'loop',
'htp.p(''<div class="home-content">',
'      <div class="overview-boxes">',
'        <div class="box">',
'          <div class="right-side">',
'            <div class="box-topic"> Clientes Activos</div>',
'            <div class="PRICE">''||u.Clientes_Activos||''</div>',
'          </div>',
'          <i class="bx bxs-id-card cart"></i>',
'        </div>',
'        <div class="box">',
'          <div class="right-side">',
'            <div class="box-topic">Comisiones Pendientes $</div>',
'            <div class="PRICE">''||u.Comisiones_Pendientes||''</div>',
'          </div>',
'          <i class="bx bxs-binoculars cart two" ></i>',
'        </div>',
'        <div class="box">',
'          <div class="right-side">',
unistr('            <div class="box-topic">P\00F3lizas Activas</div>'),
'            <div class="PRICE">''||u.Polizas_Activas||''</div>',
'          </div>',
'          <i class="bx bxs-medal cart four" ></i>',
'        </div>',
'        <div class="box">',
'          <div class="right-side">',
unistr('            <div class="box-topic">P\00F3lizas a Renovar</div>'),
'            <div class="PRICE">''||u.Polizas_Renovar||''</div>',
'          </div>',
'          <i class="bx bxs-alarm-add cart three" ></i>',
'        </div>',
'      </div>'');',
'END LOOP;',
'HTP.P(''</body>'');',
'HTP.P(''</html>'');'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
end;
